116	/**
117	 * `GPUAdapter.features` is a set-like `GPUSupportedFeatures` at runtime, but the
118	 * TS DOM lib in this project types it as an array. Handle both shapes.
119	 */
120	function adapterHasFeature(adapter: GPUAdapter, name: string): boolean {
121		const features: unknown = adapter.features;
122		if (Array.isArray(features)) return features.includes(name);
123		return (features as { has(value: string): boolean }).has(name);
124	}
