126	/** True when any session of this spec is loaded as an f16 variant. */
127	function needsShaderF16(spec: BrowserModelSpec): boolean {
128		const values = typeof spec.dtype === "string" ? [spec.dtype] : Object.values(spec.dtype);
129		return values.some((value) => value.includes("f16"));
130	}
