132	export function classifyLocalModelError(message: string, spec: BrowserModelSpec): string {
133		const lower = message.toLowerCase();
134	
135		// AutoProcessor throws this for text-only repos. It is a catalog bug, not a
136		// GPU problem — reporting it as one sends people into their driver settings.
137		if (lower.includes("image_processor_type") || lower.includes("feature_extractor_type")) {
138			return `${spec.name} has no processor config, so it must load as a text-only model. This is a Keating configuration bug — please report it.`;
139		}
140	
141		if (lower.includes("shader-f16") || lower.includes("shader_f16")) {
142			return `Your GPU does not support the WebGPU shader-f16 feature, which ${spec.name} needs. Try a smaller browser model instead.`;
143		}
144	
145		if (lower.includes("webgpu") || lower.includes("no adapter")) {
146			return "WebGPU is not supported in this browser. The browser model requires Chrome 113+ or Edge 113+. Enable hardware acceleration in your browser settings.";
147		}
148	
149		if (lower.includes("404") || lower.includes("could not locate") || lower.includes("unauthorized")) {
150			return `Could not find the model files for ${spec.id} on Hugging Face. The model may have been renamed or removed.`;
151		}
152	
153		if (
154			lower.includes("not allowed to load from")
155			|| lower.includes("failed to fetch")
156			|| lower.includes("networkerror")
157			|| lower.includes("net::")
158		) {
159			return `Could not download ${spec.name}. Check your internet connection and try again — the download is ${spec.downloadLabel}.`;
160		}
161	
162		if (
163			lower.includes("out of memory")
164			|| lower.includes("memory allocation")
165			|| lower.includes("not enough memory")
166		) {
167			return `Not enough GPU memory to load ${spec.name} (${spec.downloadLabel}). Close other GPU-heavy tabs, or pick a smaller model from the list.`;
168		}
169	
170		if (lower.includes("aborted") || lower.includes("cancelled")) {
171			return "Model loading was cancelled.";
172		}
173	
174		return message;
175	}
