177	async function checkWebGpuAvailable(
178		spec: BrowserModelSpec,
179	): Promise<{ available: boolean; reason?: string }> {
180		if (!navigator.gpu) {
181			return {
182				available: false,
183				reason: "WebGPU is not supported in this browser. The browser model requires Chrome 113+ or Edge 113+ with hardware acceleration enabled.",
184			};
185		}
186		try {
187			const adapter = await navigator.gpu.requestAdapter();
188			if (!adapter) {
189				return {
190					available: false,
191					reason: "No WebGPU adapter found. Your GPU may not support WebGPU, or hardware acceleration may be disabled. Enable it in your browser settings.",
192				};
193			}
194			// Every f16 export fails at session creation without this feature, with an
195			// error that is far less legible than saying so up front.
196		if (needsShaderF16(spec) && !adapterHasFeature(adapter, "shader-f16")) {
197			return {
198				available: false,
199				reason: `Your GPU reports no shader-f16 support, which ${spec.name} requires. Try a smaller browser model instead.`,
200			};
201		}
202			return { available: true };
203		} catch {
204			return {
205				available: false,
206				reason: "WebGPU adapter request failed. Your GPU may not support WebGPU, or hardware acceleration may be disabled in your browser settings.",
207			};
208		}
209	}
