211	export interface LocalModel {
212		loaded: boolean;
213		loading: boolean;
214		loadingProgress: number;
215		error: string | null;
216		/** Repo id of the model that is loaded or currently loading. */
217		modelId: string | null;
218		model: any | null;
219		/** Set for multimodal repos only. */
220		processor: any | null;
221		tokenizer: any | null;
222	}
223	
224	const IDLE_STATE: LocalModel = {
225		loaded: false,
226		loading: false,
227		loadingProgress: 0,
228		error: null,
229		modelId: null,
230		model: null,
231		processor: null,
232		tokenizer: null,
233	};
234	
235	class LocalModelStore {
236		private state: LocalModel = IDLE_STATE;
237		private listeners: Set<(state: LocalModel) => void> = new Set();
238		private inFlight: Promise<void> | null = null;
239		private loadEpoch = 0;
240	
241		subscribe(listener: (state: LocalModel) => void): () => void {
242			this.listeners.add(listener);
243			listener(this.state);
244			return () => this.listeners.delete(listener);
245		}
246	
247		private notify(): void {
248			this.listeners.forEach((l) => l(this.state));
249		}
250	
251		private fail(spec: BrowserModelSpec, rawMessage: string): void {
252			const message = classifyLocalModelError(rawMessage, spec);
253			this.state = { ...IDLE_STATE, error: message, modelId: spec.id };
254			this.notify();
255			console.error(`[local-model] ${spec.id} failed:`, rawMessage);
256		}
257	
258		async load(modelId: string = DEFAULT_BROWSER_MODEL_ID): Promise<void> {
259			if (this.state.loaded && this.state.modelId === modelId) return;
260			// A load for a different model supersedes the one in flight.
261			if (this.state.loading && this.state.modelId === modelId) {
262				await this.inFlight;
263				return;
264			}
265			const epoch = ++this.loadEpoch;
266			const pending = this.performLoad(modelId, epoch);
267			this.inFlight = pending;
268			try {
269				await pending;
270			} finally {
271				if (this.inFlight === pending) {
272					this.inFlight = null;
273				}
274			}
275		}
276	
277		private isCurrentLoad(epoch: number): boolean {
278			return epoch === this.loadEpoch;
279		}
280	
281		private async performLoad(modelId: string, epoch: number): Promise<void> {
282			const spec = getBrowserModel(modelId);
283			if (!spec) {
284				if (!this.isCurrentLoad(epoch)) return;
285				this.state = {
286					...IDLE_STATE,
287					error: `Unknown browser model: ${modelId}`,
288					modelId,
289				};
290				this.notify();
291				console.error(`[local-model] unknown browser model: ${modelId}`);
292				return;
293			}
294	
295			if (!this.isCurrentLoad(epoch)) return;
296			this.state = { ...IDLE_STATE, loading: true, modelId };
297			this.notify();
298	
299			try {
300				const gpuCheck = await checkWebGpuAvailable(spec);
301				if (!this.isCurrentLoad(epoch)) return;
302				if (!gpuCheck.available) {
303					this.state = { ...IDLE_STATE, error: gpuCheck.reason!, modelId };
304					this.notify();
305					console.error("[local-model] WebGPU unavailable:", gpuCheck.reason);
306					return;
307				}
308	
309				console.log(`[local-model] loading ${spec.id} (${spec.downloadLabel})`);
310	
311				const { AutoProcessor, AutoTokenizer, AutoModelForCausalLM, env } = await import(
312					"@huggingface/transformers"
313				);
314	
315				// Never attempt to resolve models from the app's own origin.
316				env.allowLocalModels = false;
317				env.useBrowserCache = true;
318	
319				// Text-only repos have no processor_config.json; AutoProcessor throws on them.
320				const processor =
321					spec.kind === "multimodal" ? await AutoProcessor.from_pretrained(spec.id) : null;
322				const tokenizer = processor
323					? processor.tokenizer
324					: await AutoTokenizer.from_pretrained(spec.id);
325	
326				const model = await AutoModelForCausalLM.from_pretrained(spec.id, {
327					dtype: spec.dtype as any,
328					device: "webgpu",
329					progress_callback: (progress: any) => {
330						if (!this.isCurrentLoad(epoch)) return;
331						if (progress.status === "progress" || progress.status === "progress_total") {
332							const pct = Math.round(progress.progress ?? 0);
333							this.state = { ...this.state, loadingProgress: pct };
334							this.notify();
335						}
336					},
337				});
338	
339				if (!this.isCurrentLoad(epoch)) return;
340	
341				this.state = {
342					loaded: true,
343					loading: false,
344					loadingProgress: 100,
345					error: null,
346					modelId: spec.id,
347					model,
348					processor,
349					tokenizer,
350				};
351				this.notify();
352				console.log(`[local-model] ${spec.id} ready`);
353			} catch (error) {
354				if (!this.isCurrentLoad(epoch)) return;
355				this.fail(spec, error instanceof Error ? error.message : String(error));
356			}
357		}
358	
359		async generate(
360			prompt: string,
361			options?: { max_length?: number; temperature?: number },
362			onToken?: (token: string) => void,
363		): Promise<string> {
364			const { model, processor, tokenizer, modelId } = this.state;
365			if (!model || !tokenizer || !modelId) {
366				throw new Error("Browser model is not loaded");
367			}
368			const spec = getBrowserModel(modelId);
369			if (!spec) throw new Error(`Unknown browser model: ${modelId}`);
370	
371			try {
372					// Multimodal templates expect typed content parts; text-only templates
373					// take a plain string.
374					const messages = [
375						{
376							role: "user",
377							content:
378								spec.kind === "multimodal" ? [{ type: "text", text: prompt }] : prompt,
379					},
380				];
381	
382				const formattedPrompt = tokenizer.apply_chat_template(messages, {
383					add_generation_prompt: true,
384					// Gemma 4 ships a thinking channel that is on unless disabled. Keating
385					// renders the reply directly, so the raw thinking tokens are noise.
386					enable_thinking: false,
387					tokenize: false,
388				});
389	
390				// The chat template already inserted the special tokens.
391				// Processors vary across Transformers.js versions; try both the explicit
392				// multimodal argument shape and the legacy single-signature shape.
393				const processMultimodal = async () => {
394					try {
395						return await processor(formattedPrompt, null, null, { add_special_tokens: false });
396					} catch (error) {
397						return await processor(formattedPrompt, { add_special_tokens: false });
398					}
399				};
400				const inputs =
401					spec.kind === "multimodal" ? await processMultimodal() : tokenizer(formattedPrompt, { add_special_tokens: false });
402	
403				const { TextStreamer } = await import("@huggingface/transformers");
404	
405				const streamer = new TextStreamer(tokenizer, {
406					skip_prompt: true,
407					skip_special_tokens: true,
408					callback_function: onToken ? (text: string) => onToken(text) : undefined,
409				});
410	
411				const temperature = options?.temperature ?? 0.7;
412				const doSample = temperature > 0;
413	
414				const outputs = await model.generate({
415					...inputs,
416					max_new_tokens: Math.max(1, options?.max_length ?? 512),
417					do_sample: doSample,
418					...(doSample ? { temperature } : {}),
419					streamer,
420				});
421	
422				const decoded = tokenizer.batch_decode(
423					outputs.slice(null, [inputs.input_ids.dims.at(-1), null]),
424					{ skip_special_tokens: true },
425				);
426	
427				return decoded[0] ?? "";
428			} catch (error) {
429				const rawMessage = error instanceof Error ? error.message : String(error);
430				console.error(`[local-model] ${spec.id} generation failed:`, rawMessage);
431				throw new Error(classifyLocalModelError(rawMessage, spec));
432			}
433		}
434	
435		getState(): LocalModel {
436			return this.state;
437		}
438	}
439	
440	export const localModel = new LocalModelStore();
